mapper.select:
SELECT numerical_value
FROM esg_metric_data
WHERE indicator_id = #{indicatorId}
  AND (facility_id = #{facilityId} OR (facility_id IS NULL AND #{facilityId} IS NULL))
ORDER BY reporting_year DESC, period_value DESC
LIMIT #{limit}

mapper.delete:
DELETE FROM esg_metric_data
WHERE id = #{id}
  AND status = CAST('REJECTED' AS data_status_enum)
